package dev.pentoshi.protonx

import dev.pentoshi.protonx.core.Srp
import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.math.BigInteger
import java.util.Base64

/** Vectors generated by protonxlib (the desktop engine) so both implementations must agree byte for byte. */
class SrpTest {
    private val vectors: JSONObject = javaClass.getResourceAsStream("/srp-vectors.json")!!
        .bufferedReader().use { JSONObject(it.readText()) }

    private fun bytes(key: String): ByteArray = Base64.getDecoder().decode(vectors.getString(key))

    @Test
    fun bcryptDigestMatchesTheDesktopEngine() {
        val digest = Srp.bcryptDigest(vectors.getString("password"), bytes("salt"))
        assertEquals(vectors.getString("bcryptDigest"), String(digest, Charsets.US_ASCII))
    }

    @Test
    fun cleartextModulusIsDecodedFromTheSignedMessage() {
        val message = """
            -----BEGIN PGP SIGNED MESSAGE-----
            Hash: SHA256

            ${vectors.getString("modulus")}
            -----BEGIN PGP SIGNATURE-----
            Version: OpenPGP.js v4.10.10
            iQEzBAEBCAAdFiEE
            -----END PGP SIGNATURE-----
        """.trimIndent()
        assertArrayEquals(bytes("modulus"), Srp.cleartextModulus(message))
    }

    @Test
    fun proofsMatchTheDesktopEngineForAFixedSecret() {
        val proofs = Srp.generateProofs(
            password = vectors.getString("password"),
            salt = bytes("salt"),
            modulus = bytes("modulus"),
            serverEphemeral = bytes("serverEphemeral"),
            secret = BigInteger(vectors.getString("secretHex"), 16),
        )
        val encoder = Base64.getEncoder()
        assertEquals(vectors.getString("clientEphemeral"), encoder.encodeToString(proofs.clientEphemeral))
        assertEquals(vectors.getString("clientProof"), encoder.encodeToString(proofs.clientProof))
        assertEquals(vectors.getString("serverProof"), encoder.encodeToString(proofs.serverProof))
    }

    @Test
    fun aShortModulusIsRejected() {
        val failure = runCatching {
            Srp.generateProofs("pw", bytes("salt"), ByteArray(128) { 1 }, bytes("serverEphemeral"))
        }.exceptionOrNull()
        assertTrue(failure?.message.orEmpty().contains("expected 2048"))
    }

    @Test
    fun anOutOfRangeServerEphemeralIsRejected() {
        val failure = runCatching {
            Srp.generateProofs("pw", bytes("salt"), bytes("modulus"), ByteArray(256) { 0xFF.toByte() })
        }.exceptionOrNull()
        assertTrue(failure?.message.orEmpty().contains("out of range"))
    }
}
